```{.r .cell-code}
library(gtsummary)

# Example data
data <- data.frame(
  age = rnorm(100, 50, 10),
  blood_pressure = rnorm(100, 120, 15),
  treatment = sample(c("A", "B"), 100, replace = TRUE)
)

# Summary statistics
data %>% 
  tbl_summary()
```

